import math

def get_prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def is_prime_power_exponent_at_least_two(n):
    if n <= 1:
        return None  # Not a power of a prime with exponent >= 2
    factors = get_prime_factorization(n)
    if len(factors) != 1:
        return None  # Not a prime power
    prime = list(factors.keys())[0]
    exponent = list(factors.values())[0]
    if exponent >= 2:
        return prime
    return None

solutions = []

# Search space for m and n is [1, 10]
for m in range(1, 11):
    for n in range(1, 11):
        X = m**2 + n
        Y = m + n**2

        # Check X
        p_X = is_prime_power_exponent_at_least_two(X)

        # Check Y
        p_Y = is_prime_power_exponent_at_least_two(Y)

        # Check if they share the same prime base p
        if p_X is not None and p_Y is not None and p_X == p_Y:
            p = p_X
            solutions.append((m, n, p))

print("Found solutions (m, n, p):")
for sol in solutions:
