def check_solution(m, n, p):
    """Checks if (m, n, p) satisfies the problem conditions."""
    if m <= 0 or n <= 0 or p <= 0 or not is_prime(p):
        return False

    # Condition 1: log_p(m^2+n) is an integer A > 1
    m2_plus_n = m*m + n
    try:
        A = round(math.log(m2_plus_n, p))
        if abs(m2_plus_n / (p**A) - 1) > 1e-9 or A <= 1:
            return False
    except ValueError:
        return False # p^A doesn't divide m^2+n or log is undefined

    # Condition 2: log_p(m+n^2) is an integer B > 1
    m_plus_n2 = m + n*n
    try:
        B = round(math.log(m_plus_n2, p))
        if abs(m_plus_n2 / (p**B) - 1) > 1e-9 or B <= 1:
            return False
    except ValueError:
        return False

    return True

def is_prime(k):
    if k < 2:
        return False
    for i in range(2, int(math.sqrt(k)) + 1):
        if k % i == 0:
            return False
    return True

